{
  "schema_version": 1,
  "id": "io.serviceradar.alpr-console",
  "name": "ALPR Synthetic Console",
  "version": "1.0.0",
  "description": "Synthetic ALPR dashboard browser module for Gate West 01 (SR-0100, TEST-742).",
  "vendor": "ServiceRadar",
  "renderer": {
    "kind": "browser_module",
    "interface_version": "dashboard-browser-module-v1",
    "artifact": "renderer.js",
    "sha256": "1f7e9db5d88883d5ef44d19cd3bef7b5e7bf5018bd3fb04e498ebe1312ce45c3",
    "trust": "trusted"
  },
  "data_frames": [
    {
      "id": "recent_plate_reads",
      "query": "in:camera_observations category:license_plate sort:timeline_ts_us:desc limit:100",
      "encoding": "json_rows",
      "required": true,
      "limit": 100,
      "refresh_interval_ms": 5000
    }
  ],
  "capabilities": [
    "camera.stream.view",
    "events.subscribe",
    "srql.execute"
  ],
  "settings_schema": {
    "type": "object",
    "properties": {
      "camera_source_id": {
        "type": "string"
      }
    }
  }
}

files.dashboard_packages/alpr-console/renderer:
export const MODULE_VERSION = "dashboard-browser-module-v1";
export function mountAlprConsole(api) {
  const streamCaps = ["camera.stream.view", "events.subscribe", "srql.execute"];
  const eventFilter = {
    class_uid: 1008,
    metadata: { service_radar: { signal_schema: { schema_id: "alpr_plate_read" } } },
  };
  return { capabilities: streamCaps, filter: eventFilter, samplePlates: ["SR-0100", "TEST-742"] };
}

